declare
  payload jsonb := '[{"seat":"W02","name":"문수빈","file":"여자 02번 문수빈.hwp","school":"다율고등학교","phone":"010-6935-2665","student_status":"재학생","building":2,"records":[{"date":"2026-07-07","original_name":"문수빈","original_date":"2026.07.07","counselor_name":"원장","content":"하이탑-준비 중\n처음엔 본다라는 초독(필요하다면 인강)\n--\n수학\n과외 숙제=풍산자,올림포스(문제 2분씩) 추천 과외날 당일 대표문제 풀기!!\n*다음 분분 인강 ebs 선택 과외진도 보다 먼저 선행\n-교과서+가벼운 문제집\n목표 방학기간에 기말고사 전부 끝내기\n수학 메쓰홀리 프로그램으로 시험!!\n영어-올림포스(2개 충분 계속 읽고 학교 기말고사 교과서 진도 알수 있음 미리 하기)\n단어장\n과학-하이탑 미리 2학기(개념) +EBS인강>>>심화 목표:2학기 전체\n국어:윤해정 나비효과.\n--","special_notes":""},{"date":"2026-07-27","original_name":"문수빈","original_date":"7.27","counselor_name":"이호진","content":"국어)\n따로 어려운 부분 없다고 합니다. 현재 학습하는 속도가 조금 느려 조금 걱정이 있다고 하여, 지금은 기초적인 부분을 채워나가는 중이라 그런것이며 후에 문제풀이 및 심화 개념 학습으로 넘어가게 되면 속도가 빨라질 것이라고 조언하였습니다.\n수학)\n공통수학2를 선행하고 있으나, 혼자 문제를 풀 때 어떤 식으로 풀이를 접근해야 할지 감을 못 잡겠다고 합니다. 고등학교에 처음 올라온 학생들이 많이 겪는 문제로 중학교 때와는 다르게 여태껏 배워왔던 개념들을 서로 연계하여 문제를 내기에 어렵다고 느끼는 듯 합니다. 이러한 과정을 겪음으로써 공통수학1 및 중학교 과정에서의 빈 부분을 메꾸는 것이 중요할 것으로 보입니다.\n영어)\n단어가 부족하여 해석에 어려움을 겪는다고 합니다. 단어장을 통한 주기적인 단어 학습이 필요할 것으로 보여, 워드마스터수능2000 단어장으로 매일 day1개씩 암기하는 것을 추천했습니다.\n통과)\n어떻게 공부하는지 방법을 모르고 있었습니다. 1학기 중간고사 때 문제를 따로 풀어보지 않고 통으로 암기하는 듯한 학습을 했다고 합니다. 따라서 완자 교재를 추천하였고, 교재를 통한 개념 반복 학습 및 내신형 문제 풀이 감각을 익힐 것을 조언하였으며, 추가로 장풍 강사를 추천하였습니다.","special_notes":""},{"date":"2026-08-11","original_name":"문수빈","original_date":"8.11","counselor_name":"최서원","content":"국어)\n마더텅 독서, 문학 매일 1지문씩 풀기\n과외하는 중\n공통수학2)\n과외하는 중\n풍산자 문제집 원의방정식 까지 완벽하게 끝내기\n영어)\n공통영어2: 2과까지 스스로 해석하기 / 2과 지문 내용 요약하기\n단어 암기 워드마스터 매일 day1씩\n*구문, 문법이 잘 안되어있음 >  EBSi  주혜연t 해석공식 3.0 추천\n*내신영어, 수능영어 공부법도 같이 상담 진행함\n통합과학)\nEBSi 강의 + 하이탑 문제집\n통합사회)\n학교 교과서 출판사에 맞는 문제집 사는 것을 추천","special_notes":""},{"date":"2026-08-15","original_name":"문수빈","original_date":"2026.08.15.","counselor_name":"원장","content":"국어:제망매가,한글 맞춤법(문제풀이x),중세국어(문제풀이)\n문제풀이 하고 가서 학교 수업시간에 복습을 하는 전략\n수학:~원방//센수b 풍산장 올림폴스 잠시 스탑// 교과서 먼저 전부풀기+인강 1강 선행\n과학:공통과학2//3단원 대응 (예습 하고 들어가기)\n--\n*학교 활동은 전부 챙기고 탐구보고서 독서록 꼭 챙경\n--\n매일 매일 학교 교육과정 그날 그날 복습하는게 핵심\n--\n현대시+고전시가 꼭 꼭 읽기\n--\n혼자 공부 하는게\nhow to 공부\n수학 문제 2분*35=70 요령 센수 대표>>홀수>>짝수\n누적복습 ! !\n--\n8월 중간 테스트","special_notes":"2안으로 들어오기"},{"date":"2026-08-27","original_name":"문수빈","original_date":"2026-08-27","counselor_name":"최지안","content":"국어: 과외 수업 열심히 다니면서 버블티 문제집으로 시험 범위 문제들 풀어주고 있습니다.\n수학: 학교 진도에 뒤처지지 않도록 풍산자로 예습하고, 원의 방정식까지 학교 프린트 다시 풀어줄 계획입니다. 과외 수업도 열심히 듣고 있습니다.\n영어: 백발백중 문제집으로 교과서 1,2과 문제들 풀어줄 계획입니다.\n통합사회: 학교 진도에 맞추어 매일 복습하고 문제 풀이 진행할 계획입니다.\n통합과학: 학교 진도에 맞추어 하이탑으로 예습하고 완자로 복습해줄 계획입니다.","special_notes":"경영학과 지망"},{"date":"2026-09-02","original_name":"문수빈 W02","original_date":"2026.09.02.","counselor_name":"원장","content":"모의고사\n국어 시간이 부족/수학 풀수 있는 문제 별로 없음\n*국어:현대시의 모든 것/고전시가의 모든 것 구입 읽기\n국어-추천)매산문/매산비 국어 공부-윤혜정의 나비효과\n국어 어법은 미리\n--\n수학\n내신 끝나면 공통수학 교과서\n--\n공통과학\n내신 끝나면 통범위로 정리\n--\n내신 준비!\n학교 공부 보다 절대 밀리지 말자~\n영어 매일 매일 2지문 모고지문 계속 들고 다니면서 독해\n수학 주마다 한번씩 교과서\n국어 자습서 공부\n과학 인강 들으며 공부","special_notes":"9월 20일경 내신 기출로 테스트"}]},{"seat":"W03","name":"권효민","file":"여자 03번 권효민.hwp","school":"교하고(2학년 자퇴)","phone":"010-7752-9331","student_status":"자퇴생","building":2,"records":[{"date":"2026-06-22","original_name":"권효민","original_date":"6.22","counselor_name":"원문 미기재","content":"국어)\n문학 수특연계교재 (현대시가,고전시가만 있는교재인 듯..) 하루5지문씩\n>끝내고 26수특 풀어보기\n비문학 빠작 하루5지문씩.. 26수특 풀어보기\n화작 매삼문 하루3강씩\n>이번주안에 마무리하고 다담 500제 풀어보기\n수학) 월수금 학원 –수분감, 자이스토리 정해진분량 매일 풀이(숙제)\n어려운부분은 아직 없음\n영어)\n독서실 단어,듣기/ 수특 라이트 하루1강+교재 단어,강의참고\n어법끝\n과학) 6/23부터 화목마다 메가스터디 강의 들어볼 예정..\n과학 제일 자신없어함, 진도 잘나가고있는지 확인","special_notes":"화목 9시에하원(필라테스)\n화작에서 시간관리 어려움.. 유형별로 푸는 교재말고 모고형식으로된 교재 풀어봐야할 듯 시간줄이기"},{"date":"2026-07-08","original_name":"권효민","original_date":"7.8","counselor_name":"이서화","content":"국어)\n비문학 (빠작) 하루 5지문 + 수능특강 푸는 중 / 문학 수능특강 연계 교재 시작할 예정\n다담 500제 내일부터 시작 가능\n매삼문 화작 완료\n수학)\n학원에서 주는 교재\n영어)\n수능특강 라이트 하루 1강 (풀이, 단어, 강의) / 어법끝\n과학)\n메가스터디 강의 수강 중\n아직까지는 크게 어려운 부분 없음","special_notes":"수능은 내년에\n과학 수강하다가 어려운 점 있으면 질문해보기"},{"date":"2026-07-21","original_name":"권효민","original_date":"7.21","counselor_name":"이서화","content":"국어)\n수능특강 비문학 매일 3지문, 문학 매일 3-4지문 / 화작 다담 매일 20-30분\n수학)\n학원에서\n미적분 개념원리, 미적분 너기출, 대수 심화 강의\n과학)\n통합과학1 강의 매일 1-2강 수강하고 인강 교재 문제풀이\n아직 크게 어렵진 않음\n영어)\n수능특강 라이트 문제풀이, 강의, 단어 / 어법끝","special_notes":""},{"date":"2026-08-04","original_name":"권효민","original_date":"8.4","counselor_name":"이서화","content":"수학)\n너기출(미적) / 대수 개념 복습 / 미적 개념원리\n학원\n국어)\n수능특강 (문학, 비문학) >> 1-2지문\n다담 화작\n영어)\n수능특강 (1지문) / 어법끝\n과학)\n강의 (9월 중순까지 완강해야..)","special_notes":"거의 수학 위주로 공부 중 (앞으로 2주 정도)"},{"date":"2026-08-11","original_name":"권효민","original_date":"8.11","counselor_name":"이서화","content":"국어)\n수능특강 문학, 비문학 / 모의고사 오답\n화작 잠시 중단\n수학)\n너기출 / 학원 시험 오답 / 개념원리\n영어)\n수능특강 문제풀이 + 단어\n과학)\n강의 (메가스터디)","special_notes":"어렵거나 밀리는 과목 없음"},{"date":"2026-08-20","original_name":"권효민","original_date":"8.20","counselor_name":"최서원","content":"국어)\n수특 비문학, 문학 각각 2~3지문씩 푸는중 / 다담 화작 주 3회\n수학)\n너기출(미적) / 개념원리 풀기\n요즘 수학 공부 비중 높음(7할정도)\n과학)\n인강듣고 문제 풀기 / 매일 수강할 예정 (한달 안에 개념 강의 끝내기)\n영어)\n수특 (하루에 미니 모의고사 한 회차씩 푸는중) / 단어 암기","special_notes":""},{"date":"2026-08-31","original_name":"권효민","original_date":"8.31","counselor_name":"최서원","content":"국어)\n수특 문학, 비문학 / 화작\n수학)\n너기출 오답+복습 / 마플시너지 시작하기 / 개념원리 복습(학원)\n영어)\n수특 2~3지문씩 / 단어 암기\n수특라이트 뒤에 미니모의고사 끝남\n과학)\n강의 듣고 문제풀이 (화목토)","special_notes":""}]},{"seat":"W05","name":"김효경","file":"여자 05번 김효경.hwp","school":"세경고","student_status":"재학생","building":2,"records":[]},{"seat":"W07","name":"이서진","file":"여자 07번 이서진.hwp","school":"문산고(졸)","phone":"010-3320-4903","student_status":"재수생","korean_subject":"화법과 작문","math_subject":"미적분","inquiry_subject_1":"생명과학Ⅰ","inquiry_subject_2":"지구과학Ⅰ","special_notes":"입학원서: 농어촌 / 농어촌 종합","building":2,"records":[{"date":"2026-08-18","original_name":"이서진","original_date":"2026.08.18.","counselor_name":"원장","content":"-생명,지구,수학,영어\n생명 1회 실모-오답+강의 듣기(1시간)+알파\n지구: 1회 실모-오답+강의 듣기(1시간)+알파\n-수학-메가스터디 1일 1모고\n수능 특강 수학 꼭 풀기 L1>L2>유제 예제 순\n-과탐 보고 점수 보고 해주세요\n**학종 선생님께 카톡으로 알려줘\n>진학사 가입 정보 넣기!!","special_notes":""},{"date":"2026-08-25","original_name":"이서진","original_date":"8.25","counselor_name":"최서원","content":"수학)\n수2, 수능특강 L1,2,3 먼저 풀고 다 풀면 미적분 수특 풀기\n수1은 L2,3 거의 다 풀음\n영어)\n수특 test2 남은거 풀고, 이버주 안에 모의고사(9월 모의고사 기출) 3회 풀기(수.금.일)\n단어, 듣기는 따로 안하는중..\n생명)\n메가스터디 백호 모의고사 시즌2 8회분 다 풀기(9모대비) 시간 재고\n오답+개념노트까지 같이 정리\n지구)\n메가스터디 오지훈 모의고사 시즌2 4회분 다 풀기(9모 대비) 시간 재고\n오답+개념노트까지 같이 정리","special_notes":"농어촌 지방 약대. 3학7, 3합8"},{"date":"2026-09-10","original_name":"이서진","original_date":"9월 10일","counselor_name":"김현서","content":"수능은 최저를 맞추기 위해 학습중입니다. 중앙대만 간호학과 농어촌 전형으로 지원 예정이고 동국대, 단국대, 이대, 경희대는 생명 or 지구 과학 교육과로 지역균형 전형으로 지원예정입니다.\n수학: 수능 특강, 기출 모의고사 위주로 학습중입니다.\n영어: 기출위주로 학습중입니다.\n생명: 백호선생님 모의고사 풀고 모르는 문제 강의 보며 수강중입니다.\n지구:오지훈 선생님 모의고사 풀고 모르는 문제 강의 보며 수강중입니다.","special_notes":"이대 경희대만 최저 2합 5\nx3234"}]},{"seat":"W08","name":"김찬율","file":"여자 08번 김찬율.hwp","school":"교하고","phone":"010-8417-6040","student_status":"재학생","korean_subject":"화법과 작문","math_subject":"확률과 통계","inquiry_subject_1":"생활과 윤리","inquiry_subject_2":"사회·문화","building":2,"records":[{"date":"2026-05-08","original_name":"김찬율","original_date":"5/8","counselor_name":"임호연","content":"국어) 윤혜정 EBS 나비효과 입문편 인강 수강중 4강째 / 현대시 + 고전시의 모든 것 각각 세 작품씩 매일 정독 / 다담 화작 500제 15문제 정도 매일 / 수특 독서 1지문->기출 풀어보기 / 수특 문학을 3작품 정도 풀기(현대시->고전시가->고전소설->현대소설)\n수학) 강의는 수강X, 짱 중요한 유형 교재 수1, 수2 거의 다 끝나감 5/10까지 끝내기 / 기출의 미래 미니(일주일 안에 끝내기) / 수특 수1, 수2, 확통 LEVEL1 우선적으로 풀기\n영어) 공부X -> 수특 영어(학교 진행중) / 독서실 듣기, 단어 꾸준히 참여하기 / 단어장 외우기 DAY1씩 외우기 / 영어 고3 기출 문제집 마더텅 하루 두 지문씩 꾸준히 매일\n세지) 공부 시작X -> EBS 수특 세지 + 강의, 문풀 병행 or 대성 세지 인강 강사 활용\n사문) 공부 시작X -> 대성 임정환 LIM IT 수강하기","special_notes":"국수영 세지사문\n한양대 에리카 미디어학과\n9시 학교 등교 저녁 먹고 5시~6시쯤 독서실 등원 새벽 1시쯤 취침\n\n원문 상담시간: 20 : 10"},{"date":"2026-06-06","original_name":"김찬율","original_date":"2026-06-06","counselor_name":"최지안","content":"국어: 화작에서 많이 틀렸다고 합니다. 수특과 EBS 위주로 공부하고 있습니다.\n수학: 확통 진도를 아직 다 못 빼서 성적이 잘 안나왔다고 합니다. 수특 풀이와 기출 모의고사 풀이 진행하고 있습니다. 앞으로도 그렇게 진행할 예정입니다.\n영어: 마더텅으로 독해 연습하고 있습니다. 매일 매일 꾸준히 학습해 주기로 했습니다.\n생윤: 임정환 선생님 림잇 강의로 학습할 예정입니다.\n사문: 임정환 선생님 림잇 강의 거의 다 끝났다고 합니다. 이번주 안으로 끝낼 수 있을 것 같다고 합니다. 림잇 끝나면 마더텅 기출로 학습할 예정이라고 합니다.","special_notes":"국어 5/ 수학 4/ 영어 3/ 생윤 사문 둘 다 5등급"},{"date":"2026-07-13","original_name":"김찬율","original_date":"7.13","counselor_name":"최서원","content":"국어)\n수특 독서, 문학 매일 1지문씩 풀고 분석하기\n화작 다담 시간 재고 풀기\n수학)\n수1, 수2 수특 level2 (2~4단원 풀어오기)\n확통 이미지t 세젤쉬 개념 끝내기, 수특 level1 끝내기\n영어)\n마더텅 기출문제집 하루에 2지문씩 독해\n단어: 매일 day1개씩 암기(독서실 단어 외에 추가로)\n사문)\n마더텅 기출 문제집\n생윤)\n대성 limit 20강까지 듣기","special_notes":"7모\n국 수 영 사문 생윤\n5/3/4/3/5"},{"date":"2026-07-27","original_name":"김찬율","original_date":"7.27","counselor_name":"최서원","content":"국어)\n수특 독서, 문학 문제풀이 / 다담 화작\n수학)\n수1 수특 level2 끝내기, 수2 수특 level2 4~6단원 풀기 / 대성마이맥 미친개념 시작하기\n영어)\n마더텅 기출문제집 2지문씩 풀기 + 단어 암기 매일 day1개씩\n사문)\n개념 복습, 마더텅 기출문제집\n생윤)\n리밋 개념 강의 + 개념 복습 + 마더텅 풀기","special_notes":"방학동안 생윤 개념 완벽하게 끝내기 목표\n영어단어 매일 꾸준히 암기하기"},{"date":"2026-08-03","original_name":"김찬율","original_date":"8.3","counselor_name":"최서원","content":"국어)\n독서, 문학 수특 각각 2지문씩 매일 / 화작 다담 ( 유형별로 담겨있는 책이라 마무리 후엔 모고 형식으로 실린 교재로 시간 줄이는 연습 하기)\n수학)\n수1 수특 레벨2 끝내기 / 수2 수특 레벨2 4~6단원 풀기 / 미친개념 시작하기 / 확통 미친기분 + 수특 레벨1 마무리\n영어)\n마더텅 영어독해 매일 2지문씩 / 단어암기 day1개씩\n사문)\n개념 복습, 마더텅 풀기\n생윤)\n개념 복습, 마더텅 풀기, limit 개념강의","special_notes":""},{"date":"2026-08-10","original_name":"김찬율","original_date":"8.10","counselor_name":"최서원","content":"국어)\n독서, 문학 수특 1지문씩 / 화작 다담\n수학)\n수1, 수2 미친개념 / 확통 미친기분\n4점짜리 발상 안 떠올랐던 문제는 며칠뒤 다시 복습해보기\n영어)\n마더텅 2지문씩 / 단어 매일 day1씩 암기\n사문)\n개념복습 / 마더텅\n생윤)\n대성 limit 강의 일주일 동안 3강 듣기 / 개념복습 / 마더텅\n생윤 개념진도 최대한 빨리 마무리하기","special_notes":""},{"date":"2026-08-20","original_name":"김찬율","original_date":"8.20","counselor_name":"최서원","content":"국어)\n수특 독서, 문학 각각 매일 1지문씩 ( 독서는 반정도 남았고, 문학은 거의 다 끝남 )\n수특 문학 틈틈이 복습해주기 / 다담 화작\n수학)\n수1 수2 미친개념 / 본교재\n생윤)\nlimit 강의 ( 다음주내로 진도 끝내기)　/ 마더텅 기출 문제집\n9모 전까지 진도 끝내기+ 전체 총복습 및 암기해보기\n사문)\n마더텅 기출 문제집\n영어)\n마더텅 2지문씩 풀기 /  단어 day1씩 암기","special_notes":""},{"date":"2026-09-12","original_name":"김찬율","original_date":"9/12","counselor_name":"김강희","content":"국어:6/수학:3/영어;3/생윤:4/사문:5\n국어: 전반적으로 글이 아니라 글자를 읽는 듯한 느낌이 들고 비문학에서 선지 분석에 시간이 너무 오래 걸린다고 합니다. 화작에서는 실수가 많다고 합니다. 현재 마더텅 기출 문제집만 풀이하고 있는데 주에 1-2회 80분 잡고 모의고사 한 회씩 풀어볼 것을 권했습니다.\n수학: 확통 심화가 완성되지 않아 오답이 많았다고 합니다. 미친개념 공통은 9월 내로, 확통은 1달 내로 끝낼 예정입니다.\n영어:빈칸 삽입과 순서 배열 파트에 취약하다고 합니다. 마더텅 풀이로 취약한 부분 집중적으로 보완하고, 주 1-2회 실전 모의고사 풀도록 권했습니다.\n생윤: 2회독 진행 중이며 아직 뒷부분이 완벽히 숙지되지 않았다고 합니다. 이에 교재 회독을 지속하되 김종익 선생님 잘잘잘 같은 기출 선지 분석 심화 커리 수강을 권했습니다.\n사문: 임팩트와 마더텅으로 학습하고 있습니다. 생윤과 마찬가지로 전반적인 개념이 완벽히 숙지되지 않았습니다. 빠른 속도로 다회독을 권했습니다.","special_notes":"탐구 2등급 목표"}]}]'::jsonb;
  item jsonb;
  entry jsonb;
  target_id uuid;
  matches integer;
  author_trigger "char";
begin
  if auth.uid() is not null then raise exception '프로젝트 관리자 SQL Editor에서 실행해 주세요.'; end if;
  -- 먼저 다섯 명 모두 이름/관/좌석을 확인합니다. 불일치 시 전체 롤백됩니다.
  for item in select * from jsonb_array_elements(payload) loop
    select count(*) into matches from public.students where name=item->>'name' and building=2 and seat_number=item->>'seat';
    if matches<>1 then raise exception '기존 2관 % % 학생이 정확히 1명이어야 합니다. 현재 %명.',item->>'seat',item->>'name',matches; end if;
    for entry in select * from jsonb_array_elements(item->'records') loop
      if (entry->>'date')::date > (now() at time zone 'Asia/Seoul')::date then raise exception '미래 상담일: %',entry->>'date'; end if;
    end loop;
  end loop;
  select tgenabled into author_trigger from pg_trigger where tgrelid='public.counseling_journals'::regclass and tgname='counseling_journals_author' and not tgisinternal;
  if author_trigger is not null then alter table public.counseling_journals disable trigger counseling_journals_author; end if;
  for item in select * from jsonb_array_elements(payload) loop
    select id into target_id from public.students where name=item->>'name' and building=2 and seat_number=item->>'seat';
    update public.students set
      phone=coalesce(item->>'phone',phone), school=item->>'school', student_status=item->>'student_status',
      korean_subject=coalesce(item->>'korean_subject',korean_subject), math_subject=coalesce(item->>'math_subject',math_subject),
      inquiry_subject_1=coalesce(item->>'inquiry_subject_1',inquiry_subject_1), inquiry_subject_2=coalesce(item->>'inquiry_subject_2',inquiry_subject_2),
      special_notes=case when item->>'special_notes' is null then special_notes
        when position(item->>'special_notes' in coalesce(special_notes,''))>0 then special_notes
        else concat_ws(E'\n',nullif(special_notes,''),item->>'special_notes') end
    where id=target_id;
    for entry in select * from jsonb_array_elements(item->'records') loop
      if not exists(select 1 from public.counseling_journals where student_id=target_id and date=(entry->>'date')::date) then
        insert into public.counseling_journals(student_id,date,counselor_id,counselor_name,content,special_notes,parent_message_sent)
        values(target_id,(entry->>'date')::date,null,entry->>'counselor_name',entry->>'content',entry->>'special_notes',false);
      end if;
    end loop;
  end loop;
  -- 실제 상담자 계정은 추정하지 않고 원문 이름만 보존. 자동 지정 트리거 상태 복원.
  if author_trigger='O' then alter table public.counseling_journals enable trigger counseling_journals_author;
  elsif author_trigger='A' then alter table public.counseling_journals enable always trigger counseling_journals_author;
  elsif author_trigger='R' then alter table public.counseling_journals enable replica trigger counseling_journals_author;
  end if;
end;
